  "logo_url": "https://res.cloudinary.com/potup3yi/image/upload/v1793499107/vvqemcm3gkjsko5m6unw.png",
  "favicon_url": "https://res.cloudinary.com/potup3yi/image/upload/v1793499107/vvqemcm3gkjsko5m6unw.png",
